Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>

using namespace std;
typedef long long LL;
const int N=10, M=25, S=1048580, MOD=1000000007;
int n,p[N][N],ma[N][N],bin[M],a[N],b[N],f[S],g[S],tot,id[70],pts[M][N],sta[M];
bool vis[N];

int qpow(int base,int exp)
{
    int res=1;
    while (exp)
    {
        if (exp&1) res=(LL)res*base%MOD;
        base=(LL)base*base%MOD; exp>>=1;
    }
    return res;
}

void setup()
{
    bin[0]=1;
    for (int i=1;i<=20;i++) bin[i]=bin[i-1]*2;
    scanf("%d",&n);
    int inv= qpow(100,MOD-2);
    for (int i=1;i<=n;i++)
        for (int j=1;j<=n;j++)
            scanf("%d",&p[i][j]),p[i][j]=(LL)p[i][j]*inv%MOD;
    while (n<6) n++, p[n][n]=1;
}

bool can_match(int x)
{
    if (x>3) return true;
    for (int i=1;i<=3;i++)
        if (!vis[i]&&ma[a[x]][b[i]])
        {
            vis[i]=true;
            if (can_match(x+1)) return true;
            vis[i]=false;
        }
    return false;
}

void dfs_explore(int x,int y,int prob)
{
    if (x>3)
    {
        int sum=0;
        for (int i=1;i<=tot;i++)
        {
            for (int j=1;j<=3;j++) b[j]=pts[i][j];
            if (can_match(1)) sum+=bin[i-1];
        }
        (f[sum]+=prob)%=MOD;
        return;
    }
    ma[a[x]][y]=0;
    if (y==n) dfs_explore(x+1,1,(LL)prob*(1-p[a[x]][y])%MOD);
    else dfs_explore(x,y+1,(LL)prob*(1-p[a[x]][y])%MOD);
    ma[a[x]][y]=1;
    if (y==n) dfs_explore(x+1,1,(LL)prob*p[a[x]][y]%MOD);
    else dfs_explore(x,y+1,(LL)prob*p[a[x]][y]%MOD);
}

void generate_states(int x,int y,int s)
{
    if (y==3)
    {
        id[s]=++tot;sta[tot]=s;
        for (int i=1;i<=3;i++) pts[tot][i]=a[i];
        return;
    }
    if (x>n) return;
    generate_states(x+1,y,s);
    a[y+1]=x;
    generate_states(x+1,y+1,s+bin[x-1]);
}

void precompute()
{
    for (int i=0;i<tot;i++)
        for (int j=0;j<bin[tot];j++)
            if (j&bin[i]) (g[j]+=g[j^bin[i]])%=MOD;
}

int main()
{
    setup();
    generate_states(1,0,0);
    a[1]=1; a[2]=2; a[3]=3;
    dfs_explore(1,1,1);
    for (int i=0;i<bin[tot];i++)
    {
        int t=0;
        for (int j=1;j<=tot;j++)
        {
            int rev=id[bin[n]-1-sta[j]];
            if (i&bin[j-1]) t+=bin[rev-1];
        }
        g[t]=f[i]; f[i]=0;
    }
    a[1]=4; a[2]=5; a[3]=6;
    dfs_explore(1,1,1);
    precompute();
    int result=0;
    for (int i=0;i<bin[tot];i++)
        (result+=(LL)f[i]*g[bin[tot]-1-i]%MOD)%=MOD;
    printf("%d\n",(1-result+MOD)%MOD);
    return 0;
}
